// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _testWithdraw(address _newOwner, uint256 _value) internal {
        vm.assume(msg.sender != c.owner() && _newOwner != msg.sender);
        vm.assume(_newOwner != address(this));
        vm.assume(c.owner() != address(this));
        vm.assume(_value <= address(c).balance);
        bool ok;
        try c.withdraw(_value) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }

    function testFuzz_testWithdraw(address _newOwner, uint256 _value) public {
        vm.assume(_newOwner.code.length == 0 && uint160(_newOwner) > 0xffff && _newOwner != address(this) && _newOwner != address(c) && _newOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _newOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && _newOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _newOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _testWithdraw(_newOwner, _value);
    }

    receive() external payable {}
}
